## Submitted testbench
```systemverilog
module tb;

  // Parameters
  localparam int DATA_WIDTH = 8;
  localparam int CLK_PERIOD = 8;               // 125 MHz
  localparam logic [15:0] PRESCALE = 16'd5;    // Typical prescale value

  // Clock and reset
  logic clk = 0;
  logic rst = 1;

  // AXI‑Stream ports (not used for stimulus)
  logic [DATA_WIDTH-1:0] s_axis_tdata = '0;
  logic                  s_axis_tvalid = 0;
  logic                  s_axis_tready;
  logic [DATA_WIDTH-1:0] m_axis_tdata;
  logic                  m_axis_tvalid;
  logic                  m_axis_tready;

  // UART interface signals
  logic                  rxd;
  logic                  txd;
  logic                  tx_busy;
  logic                  rx_busy;
  logic                  rx_overrun_error;
  logic                  rx_frame_error;

  // Configuration input
  logic [15:0]           prescale;

  // Tie off AXI‑Stream "ready" so that back‑pressure is never violated
  assign m_axis_tready = 1'b1;
  assign prescale      = PRESCALE;

  // Clock generator
  always #(CLK_PERIOD/2) clk = ~clk;

  // Reset stimulus
  initial begin
    rst = 1;
    #(CLK_PERIOD*2);
    rst = 0;
    #(CLK_PERIOD*5);          // give the design time to come out of reset
  end

  // -------------------------------------------------
  // Task: drive a UART frame on rxd
  // -------------------------------------------------
  task automatic drive_frame(input byte unsigned data, input logic stop_high);
    int unsigned bit_clks;
    int i;

    // --- start bit (low) ------------------------------------------------
    rxd = 1'b0;
    bit_clks = int'(PRESCALE) * 8;
    repeat (bit_clks) @(negedge clk);

    // --- data bits (MSB‑first) -----------------------------------------
    for (i = DATA_WIDTH-1; i >= 0; i--) begin
      rxd = data[i];
      repeat (bit_clks) @(negedge clk);
    end

    // --- stop bit --------------------------------------------------------
    rxd = stop_high ? 1'b1 : 1'b0;
    repeat (bit_clks) @(negedge clk);

    // Idle condition after a frame
    rxd = 1'b1;
    repeat (bit_clks) @(negedge clk);
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // Wait until reset is released
    @(negedge rst);
    @(posedge rst);
    #1;

    // 1) Send a good frame with data 0xA5 and a high stop bit
    drive_frame(8'hA5, 1'b1);   // stop bit = 1 → normal acceptance

    // 2) Send a frame that ends with a low stop bit (frame error)
    //    The payload data is 0x5A, which will be captured in data_reg
    drive_frame(8'h5A, 1'b0);   // stop bit = 0 → frame_error asserted

    // 3) Allow the coverage point to be sampled
    //    The property is evaluated on every rising edge with rst low.
    //    A short wait ensures we observe the correct cycle.
    repeat (20) @(posedge clk);

    // 4) End simulation cleanly
    $finish;
  end

endmodule
